import{_ as i,a0 as a,w as s,s as u,ao as l,I as n,x as d,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux 命令列簡介 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 命令列簡介 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 命令列簡介 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 命令列簡介 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200131 Intro to the Linux command line","title":"Linux 命令列簡介","tag":"202002","desc":""},"relativePath":"202002/20200131 Intro to the Linux command line.md","filePath":"[post].md"}'),p={name:"202002/20200131 Intro to the Linux command line.md"};function m(c,t,h,x,w,T){const e=a("Link");return s(),u("div",null,[t[18]||(t[18]=l('<h1 id="linux-命令列簡介" tabindex="-1">Linux 命令列簡介 <a class="header-anchor" href="#linux-命令列簡介" aria-label="Permalink to “Linux 命令列簡介”">​</a></h1><blockquote><p>下面是一些針對剛開始使用 Linux 命令列的人的熱身練習。警告：它可能會上癮。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2020/01/cmd_linux-control_linux-logo_-100828420-large.jpg" alt=""></p><p>如果你是 Linux 新手，或者從來沒有花時間研究過命令列，你可能不會理解為什麼這麼多 Linux 愛好者坐在舒適的桌面前興奮地輸入命令來使用大量工具和應用。在這篇文章中，我們將快速瀏覽一下命令列的奇妙之處，看看能否讓你着迷。</p><p>首先，要使用命令列，你必須打開一個命令工具（也稱為“命令提示符”）。如何做到這一點將取決於你運行的 Linux 版本。例如，在 RedHat 上，你可能會在屏幕頂部看到一個 “Activities” 選項卡，它將打開一個選項列表和一個用於輸入命令的小窗口（類似 “cmd” 為你打開的窗口）。在 Ubuntu 和其他一些版本中，你可能會在屏幕左側看到一個小的終端圖標。在許多系統上，你可以同時按 <code>Ctrl+Alt+t</code> 鍵打開命令窗口。</p><p>如果你使用 PuTTY 之類的工具登錄 Linux 系統，你會發現自己已經處於命令列界面。</p><p>一旦你得到你的命令列窗口，你會發現自己坐在一個提示符面前。它可能只是一個 <code>$</code> 或者像 <code>user@system:~$</code> 這樣的東西，但它意味着系統已經準備好為你運行命令了。</p>',7)),n("p",null,[t[1]||(t[1]=d("一旦你走到這一步，就應該開始輸入命令了。下面是一些要首先嚐試的命令，以及這裏是一些特別有用的命令的 ",-1)),o(e,{href:"https://www.networkworld.com/article/3391029/must-know-linux-commands.html"},{default:r(()=>[...t[0]||(t[0]=[d("PDF",-1)])]),_:1}),t[2]||(t[2]=d(" 和適合打印和做成卡片的雙面命令手冊。",-1))]),t[19]||(t[19]=l('<div class="table-wrap"><table><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>pwd</code></td><td>顯示我在文件系統中的位置（在最初進入系統時運行將顯示主目錄）</td></tr><tr><td><code>ls</code></td><td>列出我的文件</td></tr><tr><td><code>ls -a</code></td><td>列出我更多的文件（包括隱藏文件）</td></tr><tr><td><code>ls -al</code></td><td>列出我的文件，並且包含很多詳細信息（包括日期、文件大小和權限）</td></tr><tr><td><code>who</code></td><td>告訴我誰登錄了（如果只有你，不要失望）</td></tr><tr><td><code>date</code></td><td>日期提醒我今天是星期幾（也顯示時間）</td></tr><tr><td><code>ps</code></td><td>列出我正在運行的進程（可能只是你的 shell 和 <code>ps</code> 命令）</td></tr></tbody></table></div><p>一旦你從命令列角度習慣了 Linux 主目錄之後，就可以開始探索了。也許你會準備好使用以下命令在文件系統中閒逛：</p><div class="table-wrap"><table><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>cd /tmp</code></td><td>移動到其他文件夾（本例中，打開 <code>/tmp</code> 文件夾）</td></tr><tr><td><code>ls</code></td><td>列出當前位置的文件</td></tr><tr><td><code>cd</code></td><td>回到主目錄（不帶參數的 <code>cd</code> 總是能將你帶回到主目錄）</td></tr><tr><td><code>cat .bashrc</code></td><td>顯示文件的內容（本例中顯示 <code>.bashrc</code> 文件的內容）</td></tr><tr><td><code>history</code></td><td>顯示最近執行的命令</td></tr><tr><td><code>echo hello</code></td><td>跟自己説 “hello”</td></tr><tr><td><code>cal</code></td><td>顯示當前月份的日曆</td></tr></tbody></table></div><p>要了解為什麼高級 Linux 用户如此喜歡命令列，你將需要嘗試其他一些功能，例如重定向和管道。“重定向”是當你獲取命令的輸出並將其放到文件中而不是在屏幕上顯示時。“管道”是指你將一個命令的輸出發送給另一條將以某種方式對其進行操作的命令。這是可以嘗試的命令：</p><div class="table-wrap"><table><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>echo &quot;echo hello&quot; &gt; tryme</code></td><td>創建一個新的文件並將 “echo hello” 寫入該文件</td></tr><tr><td><code>chmod 700 tryme</code></td><td>使新建的文件可執行</td></tr><tr><td><code>tryme</code></td><td>運行新文件（它應當運行文件中包含的命令並且顯示 “hello” ）</td></tr><tr><td><code>ps aux</code></td><td>顯示所有運行中的程序</td></tr><tr><td>`ps aux</td><td>grep $USER`</td></tr><tr><td><code>echo $USER</code></td><td>使用環境變量顯示你的用户名</td></tr><tr><td><code>whoami</code></td><td>使用命令顯示你的用户名</td></tr><tr><td>`who</td><td>wc -l`</td></tr></tbody></table></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>一旦你習慣了基本命令，就可以探索其他命令並嘗試編寫腳本。 你可能會發現 Linux 比你想像的要強大並且好用得多.</p><hr>',8)),n("p",null,[t[4]||(t[4]=d("via: ",-1)),o(e,{href:"https://www.networkworld.com/article/3518440/intro-to-the-linux-command-line.html"},{default:r(()=>[...t[3]||(t[3]=[d("https://www.networkworld.com/article/3518440/intro-to-the-linux-command-line.html",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=d("作者：",-1)),o(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:r(()=>[...t[5]||(t[5]=[d("Sandra Henry-Stocker",-1)])]),_:1}),t[10]||(t[10]=d(" 選題：",-1)),o(e,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[6]||(t[6]=[d("lujun9972",-1)])]),_:1}),t[11]||(t[11]=d(" 譯者：",-1)),o(e,{href:"https://github.com/qianmingtian"},{default:r(()=>[...t[7]||(t[7]=[d("qianmingtian",-1)])]),_:1}),t[12]||(t[12]=d(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[8]||(t[8]=[d("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=d("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[d("LCTT",-1)])]),_:1}),t[16]||(t[16]=d(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[d("Linux中國",-1)])]),_:1}),t[17]||(t[17]=d(" 榮譽推出",-1))])])}const g=i(p,[["render",m]]);export{f as __pageData,g as default};
